{"expected_revision_id": "8468ace0-4870-40b6-9a10-6d93ac4390ea", "source": "module counter (
    input  wire       clk,
    input  wire       rst,
    output reg  [3:0] count
);

    always @(posedge clk) begin
        if (rst)
            count <= 4'b0000;
        else
            count <= count + 4'b0001;
    end

endmodule
"}
